    def build(n, mode):
        vals = [rng.randint(-1000, 1000) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        if mode in ('random', 'deep'):
            slots = [(0, 0), (0, 1)]
            for i in range(1, n):
                if mode == 'random':
                    j = rng.randrange(len(slots))
                else:
                    j = len(slots) - 1 - rng.randrange(min(len(slots), 4))
                slots[j], slots[-1] = slots[-1], slots[j]
                p, s = slots.pop()
                if s == 0:
                    L[p] = i
                else:
                    R[p] = i
                slots.append((i, 0))
                slots.append((i, 1))
        else:
            for i in range(1, n):
                if mode == 'left':
                    L[i - 1] = i
                elif mode == 'right':
                    R[i - 1] = i
                elif mode == 'zig':
                    if i % 2:
                        L[i - 1] = i
                    else:
                        R[i - 1] = i
                elif mode == 'zag':
                    if i % 2:
                        R[i - 1] = i
                    else:
                        L[i - 1] = i
                else:
                    p = (i - 1) // 2
                    if i % 2:
                        L[p] = i
                    else:
                        R[p] = i
